/*------------------------------------------------------------------------------------------------------------------------------------------------------------------------AUTOR: ROBERTO RECIFEDATA : 17/07/2023DESCRICAO: CONFERENCIA PEDIDOS COMPRAS------------------------------------------------------------------------------------------------------------------------------------------------------------------------SP_CONFERENCIA_PEDIDOS_COMPRAS '20230307','20230307',2------------------------------------------------------------------------------------------------------------------------------------------------------------------------DROP PROCEDURE SP_CONFERENCIA_PEDIDOS_COMPRAS------------------------------------------------------------------------------------------------------------------------------------------------------------------------*/CREATE PROCEDURE [dbo].[SP_CONFERENCIA_PEDIDOS_COMPRAS](	@MV_PAR01		VARCHAR(08),	@MV_PAR02		VARCHAR(08),	@MV_PAR03		FLOAT)	AS------------------------------------------------------------------------------------------------------------------------------------------------------------------------SET NOCOUNT ON -------------------------------------------------------------------------------------------------------------------------------------------------------------------------- ANALITICO------------------------------------------------------------------------------------------------------------------------------------------------------------------------IF @MV_PAR03=1 BEGIN ------------------------------------------------------------------------------------------------------------------------------------------------------------------------SELECT	CONVERT(VARCHAR(10),CONVERT(DATETIME,C7_EMISSAO),103) AS 'EMISSAO',		CONVERT(VARCHAR(10),CONVERT(DATETIME,C7_DATPRF),103) AS 'PREV.ENTREGA',		C7_NUM PEDIDO,		C7_FORNECE FORNECEDOR,		C7_LOJA LOJA,		A2_NOME NOME,		C7_PRODUTO PRODUTO,		C7_DESCRI DESCRICAO,		C7_QUANT QUANTIDADE,		C7_PRECO PRECO,		C7_TOTAL TOTAL,		C7_CC 'C.C',		DESCRICAO=(SELECT CTT_DESC01 FROM CTT010 WHERE CTT_FILIAL='0101' AND CTT_CUSTO=C7_CC AND D_E_L_E_T_<>'*'),		'NOTA'=ISNULL((SELECT TOP 1 D1_DOC+'/'+D1_SERIE FROM SD1010 WHERE D1_FILIAL='0101' AND D1_PEDIDO=C7_NUM AND D1_ITEMPC=C7_ITEM AND D_E_L_E_T_<>'*'),''),		C7_COND 'COND.PAGTO.',		'CONDICAO'=(SELECT E4_DESCRI FROM SE4010 WHERE E4_FILIAL='0101' AND E4_CODIGO=C7_COND AND D_E_L_E_T_<>'*')FROM	SC7010 SC7,SA2010 SA2WHERE	C7_FILIAL='0101'		AND C7_EMISSAO BETWEEN @MV_PAR01 AND @MV_PAR02		AND SC7.C7_FORNECE+SC7.C7_LOJA=SA2.A2_COD+SA2.A2_LOJA		AND SA2.A2_FILIAL=''		AND SC7.D_E_L_E_T_<>'*'		AND SA2.D_E_L_E_T_<>'*'		AND SC7.C7_RESIDUO=''ORDER BY C7_EMISSAO,C7_NUM,C7_DESCRI------------------------------------------------------------------------------------------------------------------------------------------------------------------------END-------------------------------------------------------------------------------------------------------------------------------------------------------------------------- SINTETICO------------------------------------------------------------------------------------------------------------------------------------------------------------------------IF @MV_PAR03=2 BEGIN ------------------------------------------------------------------------------------------------------------------------------------------------------------------------SELECT	CONVERT(VARCHAR(10),CONVERT(DATETIME,C7_EMISSAO),103) AS 'EMISSAO',		CONVERT(VARCHAR(10),CONVERT(DATETIME,C7_DATPRF),103) AS 'PREV.ENTREGA',		C7_NUM PEDIDO,		C7_FORNECE FORNECEDOR,		C7_LOJA LOJA,		A2_NOME NOME,		SPACE(15) PRODUTO,		SPACE(50) DESCRICAO,		COUNT(*) QUANTIDADE,		0 PRECO,		SUM(C7_TOTAL) TOTAL,		SPACE(10) 'C.C',		SPACE(40) DESCRICAO,		'NOTA'=ISNULL((SELECT TOP 1 D1_DOC+'/'+D1_SERIE FROM SD1010 WHERE D1_FILIAL='0101' AND D1_PEDIDO=C7_NUM AND D_E_L_E_T_<>'*'),''),		C7_COND 'COND.PAGTO.',		'CONDICAO'=(SELECT E4_DESCRI FROM SE4010 WHERE E4_FILIAL='0101' AND E4_CODIGO=C7_COND AND D_E_L_E_T_<>'*')FROM	SC7010 SC7,SA2010 SA2WHERE	C7_FILIAL='0101'		AND C7_EMISSAO BETWEEN @MV_PAR01 AND @MV_PAR02		AND SC7.C7_FORNECE+SC7.C7_LOJA=SA2.A2_COD+SA2.A2_LOJA		AND SA2.A2_FILIAL=''		AND SC7.D_E_L_E_T_<>'*'		AND SA2.D_E_L_E_T_<>'*'GROUP BY CONVERT(VARCHAR(10),CONVERT(DATETIME,C7_EMISSAO),103),CONVERT(VARCHAR(10),CONVERT(DATETIME,C7_DATPRF),103),C7_NUM,C7_FORNECE,C7_LOJA,A2_NOME,C7_CONDORDER BY CONVERT(VARCHAR(10),CONVERT(DATETIME,C7_EMISSAO),103),C7_NUM------------------------------------------------------------------------------------------------------------------------------------------------------------------------END------------------------------------------------------------------------------------------------------------------------------------------------------------------------SET NOCOUNT OFF ------------------------------------------------------------------------------------------------------------------------------------------------------------------------